#include "server_performance_store.h"

#include <cassert>
#include <cstdio>
#include <string>
#include <sys/stat.h>

int main(){
    const std::string path="dist/server-performance-test.db";std::remove(path.c_str());
    ServerPerformanceStore store(path);assert(store.Start(900));store.RecordHttpDuration(750000,"/api/player/gravestones");
    ServerPerformanceInput first;first.engineTickMs=16.7;first.zanikGameThreadMs=.2;first.engineTicks=52;first.averagePingMs=42;first.maximumPingMs=55;first.onlinePlayers=1;first.players={{"player-1","Test Player",55,2}};assert(store.Sample(first,1010));
    ServerPerformanceInput spike;spike.engineTickMs=125;spike.zanikGameThreadMs=.4;spike.engineTicks=50;spike.gameThreadHitches=1;spike.averagePingMs=380;spike.maximumPingMs=380;spike.onlinePlayers=1;spike.players={{"player-1","Test Player",380,4}};spike.attributions={{"gravestones","claim_all_owner","player-1","Test Player","website",1800}};assert(store.Sample(spike,1020));spike.players[0].connectedSeconds=6;assert(store.Sample(spike,1022));
    const auto warmup=store.Json(0);assert(warmup.find("Sustained network latency")==std::string::npos);assert(warmup.find("\"suppressedLoginPingSamples\":2")!=std::string::npos);
    spike.gameThreadHitches=0;for(std::uint64_t i=0;i<3;++i){spike.players[0].connectedSeconds=12+i*2;assert(store.Sample(spike,1024+i*2));}
    const auto json=store.Json(0);assert(json.find("\"sessionStartedAt\":900")!=std::string::npos);assert(json.find("\"engineTicks\":302")!=std::string::npos);assert(json.find("\"maximumEngineTickMs\":125.00")!=std::string::npos);assert(json.find("Engine dispatcher work caused a game-thread hitch")!=std::string::npos);assert(json.find("Slow Zanik game-thread work · gravestones")!=std::string::npos);assert(json.find("claim_all_owner took 1.80 ms of Zanik-added game-thread work, initiated by Test Player")!=std::string::npos);assert(json.find("Sustained network latency · Test Player")!=std::string::npos);assert(json.find("\"clientPacketLossAvailable\":false")!=std::string::npos);assert(json.find("\"averageJitterMs\"")!=std::string::npos);assert(json.find("\"networkRxKiBps\"")!=std::string::npos);assert(json.find("\"httpMaximumMs\":750.00")!=std::string::npos);assert(json.find("Slow web request · /api/player/gravestones")!=std::string::npos);assert(json.find("\"sampleIntervalSeconds\":2")!=std::string::npos);assert(json.find("\"attributionDrops\":0")!=std::string::npos);assert(json.find("Slow web request")<json.find("Sustained network latency"));
    const auto recent=store.Json(0,true);assert(recent.find("Sustained network latency")<recent.find("Slow web request"));
    store.RecordHttpDuration(2050000,"@request-receive-timeout");assert(store.Sample(ServerPerformanceInput{},1032));const auto timeoutJson=store.Json(0);assert(timeoutJson.find("Incomplete web connection · receive timeout")!=std::string::npos);assert(timeoutJson.find("did not send a complete HTTP request within two seconds")!=std::string::npos);assert(timeoutJson.find("uncaptured route")==std::string::npos);
    store.RecordHttpDuration(630000,"/assets/test.png");assert(store.Sample(ServerPerformanceInput{},1034));const auto assetJson=store.Json(0);assert(assetJson.find("client connection or network path is the stronger lead")!=std::string::npos);assert(assetJson.find("cannot prove which side caused it")!=std::string::npos);
    ServerPerformanceInput native;native.attributions={{"inventory","in-game item move","player-1","Test Player","game",4040,"native-game"}};assert(store.Sample(native,1036));const auto nativeJson=store.Json(0);assert(nativeJson.find("Dragonwilds game operation · inventory")!=std::string::npos);assert(nativeJson.find("Dragonwilds' in-game item move took 4.04 ms inside the original game function")!=std::string::npos);assert(nativeJson.find("Zanik observer work is measured separately")!=std::string::npos);assert(nativeJson.find("\"severity\":\"warning\",\"title\":\"Dragonwilds game operation · inventory")!=std::string::npos);
    struct stat mode{};assert(stat(path.c_str(),&mode)==0&&(mode.st_mode&0777)==0600);const auto diagnostics=store.Diagnostics();assert(diagnostics.samples==9&&diagnostics.persistenceHealthy);std::remove(path.c_str());
    const std::string completePath="dist/server-performance-complete-test.db";std::remove(completePath.c_str());ServerPerformanceStore complete(completePath);assert(complete.Start(1900));for(std::uint64_t i=0;i<15;++i){complete.RecordHttpDuration((500+i)*1000,"/slow/"+std::to_string(i));ServerPerformanceInput sample;sample.engineTickMs=1;sample.zanikGameThreadMs=.1;assert(complete.Sample(sample,2000+i*2));}const auto completeJson=complete.Json(0);std::size_t titles=0,cursor=0;while((cursor=completeJson.find("\"title\":",cursor))!=std::string::npos){++titles;cursor+=8;}assert(titles==10);assert(completeJson.find("\"insightTotal\":15")!=std::string::npos);assert(completeJson.find("\"insightPage\":0")!=std::string::npos);const auto secondPage=complete.Json(0,false,1);titles=0;cursor=0;while((cursor=secondPage.find("\"title\":",cursor))!=std::string::npos){++titles;cursor+=8;}assert(titles==5);assert(secondPage.find("\"insightPage\":1")!=std::string::npos);std::remove(completePath.c_str());
}
